// Portable Hexagon Functions by Bingle - 1/14/2025
// See the common tab for the functions themselves.
// Feel free to use them for whatever you want

// See also: https://www.redblobgames.com/grids/hexagons/

#define MIXRIGHT clamp( centered.x-centered.y*0.1-iResolution.x*(1.0/6.0),0.0,1.0)
#define MIXLEFT  clamp(-centered.x+centered.y*0.1-iResolution.x*(1.0/6.0),0.0,1.0)

vec3 hash32(vec2 p){
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 centered = fragCoord-iResolution.xy*0.5;
    vec2 uv = centered/iResolution.y*10.0-vec2(iTime,0.1*iTime);
    // Hexagon axial coordinates (rounded)
    vec2 hex = hexRound(pxToHex(uv));
    vec3 hexCol = hash32(hex);
    // Hexagon position in UV space
    vec2 hexPos = hexToPx(hex);
    // Coordinates local to hexagon center
    vec2 localCoords = uv-hexPos;

    vec3 col = vec3(length(localCoords)); // Center panel
    col = mix(col,hexCol,MIXLEFT); // Left panel
    col = mix(col,vec3(normalize(localCoords)*0.5+0.5,0.0),MIXRIGHT); // Right panel

    // Output to screen
    fragColor = vec4(col,1.0);
}

#define SIZE 1.0

vec2 hexToPx(vec2 hex){
    return vec2(
        1.5*hex.x,
        sqrt(3.0)/2.0 * hex.x + sqrt(3.0)*hex.y
    )*SIZE;
}

vec2 pxToHex(vec2 px){
    return vec2(
        2.0/3.0*px.x,
        -1.0/3.0*px.x+sqrt(3.0)/3.0*px.y
    )/SIZE;
}

vec2 hexRound(vec2 hex){
    vec2 grid = round(hex);
    hex-=grid;
    if (abs(hex.x)>=abs(hex.y)){
        return vec2(round(hex.x + 0.5*hex.y), 0)+grid;
    }else{
        return vec2(0, round(hex.y + 0.5*hex.x))+grid;
    }
}
